theorem parseCat_expression_same_source {p q : Nat → P (Syn .expr)} {src : Bytes}
    {a b : Syn .expr} {la lb : List Choice}
    (accepted : parseCat p src = .ok (a, la)) (accepted' : parseCat q src = .ok (b, lb)) : a = b

def typedParameters (n : Nat) : Nat → Syn (.list .param)
  | 0 => .nil
  | m + 1 => .cons (typedParameter n) (typedParameters n m)

theorem qBalanced_conditional {c a b : List Tok}
    (hc : QBalanced c) (ha : QBalanced a) (hb : QBalanced b) :
    QBalanced (c ++ .punct .question :: (a ++ .punct .colon :: b))

def optionalHoles : Nat → Syn (.list (.opt .expr))
  | 0 => .nil
  | n + 1 => .cons .none (optionalHoles n)

def pop (k : Bracket) : List Bracket → Option (List Bracket)
  | [] => none
  | h :: s => if h = k then some s else none

def firstTop (p : Tok → Bool) (s : List Bracket) : List Tok → Option (Nat × Tok)
  | [] => none
  | t :: ts =>
    if s.isEmpty && p t then some (0, t)
    else (step s t).bind fun next =>
      (firstTop p next ts).map (offset 1)

theorem skip_enclose (p : Tok → Bool) (k : Bracket) {ts : List Tok}
    (h : Balanced ts) (hop : p (openTok k) = false) :
    skip p [] (openTok k :: (ts ++ [closeTok k])) = some []
